package com.pathland.view;

/**
 * A value — typically an enum — that maps to a numeric protocol code (its
 * {@code wire}). Lets a reactive config member of an enum type (e.g.
 * {@code Signal<ShapeKind>}) be normalized to a property's {@code F32} value by
 * {@code com.pathland.view.emit.ReactiveValues}.
 */
public interface WireValue {

    /** The numeric protocol code for this value. */
    int wire();
}

input.newString:
import com.pathland.view.Color;
import com.pathland.view.WireValue;
import com.pathland.view.signal.Signal;

/**
 * Converts a reactive signal's value into the typed property value stored on a
 * {@link PathlandNode}. Booleans become raw {@code 1}/{@code 0}; wire-typed
 * enums ({@link WireValue}) become their numeric code; other values pass through
 * (the property's wire value type drives the final encoding).
 */
public final class ReactiveValues {

    private ReactiveValues() {}

    /** Read the signal and normalize its value for storage as a node property. */
    public static Object from(int property, Signal<?> signal) {
        Object value = signal.get();
        if (value instanceof Boolean b) {
            return b ? 1 : 0;
        }
        if (value instanceof Color) {
            return value;
        }
        if (value instanceof Float || value instanceof Integer) {
            return value;
        }
        if (value instanceof String) {
            return value;
        }
        if (value instanceof WireValue w) {
            return (float) w.wire();
        }
        throw new IllegalArgumentException(
                "Unsupported reactive property value " + value + " for property 0x"
                        + Integer.toHexString(property));
    }
}

