package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.signal.WritableSignal;

import java.util.function.Consumer;

import static com.pathland.view.signal.Signals.computed;

/**
 * The now-playing sidebar (right): the current track's large album art, its
 * title/artist, and the next two tracks. Everything is bound to the current
 * {@code trackIndex}, so a track change re-emits only this pane's deltas.
 *
 * <p>Configured with {@code NowPlayingSidebar.with(s -> s.trackIndex(...))} — a
 * private constructor keeps creation on the configurator (spec DSL.md §2).
 */
public final class NowPlayingSidebar implements View, Configurable<NowPlayingSidebar.Config> {

    /** {@link NowPlayingSidebar} values. */
    public static final class Config implements View.Config {

        private WritableSignal<Integer> trackIndex;

        /** The current track index (drives the art + up-next). */
        public Config trackIndex(WritableSignal<Integer> trackIndex) {
            this.trackIndex = trackIndex;
            return this;
        }
    }

    private final Config config;

    private NowPlayingSidebar(Config config) {
        this.config = config;
    }

    /** Configure the sidebar's values. */
    public static ViewBuilder<NowPlayingSidebar, Config> with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new NowPlayingSidebar(config));
    }

    /** Apply modifiers to a bare sidebar. */
    public static ViewBuilder<NowPlayingSidebar, Config> modifiers(ViewModifier... modifiers) {
        return new ViewBuilder<>(new NowPlayingSidebar(new Config())).modifiers(modifiers);
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public View body() {
        return VStack
                .modifiers(
                        Padding.with(p -> p.uniform(24)),
                        Background.with(b -> b.color(MusicPlayerView.SIDEBAR_BG)),
                        Frame.with(f -> f.width(MusicPlayerView.SIDEBAR_WIDTH).height(Commands.Size.FILL)))
                .with(v -> v.alignment(HorizontalAlignment.LEADING).spacing(14))
                .children(
                        Text.with(t -> t.text("Now Playing")).modifiers(
                                FontSize.with(s -> s.size(18)), FontWeight.BOLD, AccessibilityRole.with(a -> a.role(Roles.HEADER))),
                        Image.with(i -> i.source(computed(() -> MusicPlayerView.at(config.trackIndex.get()).cover()))).modifiers(
                                Frame.with(f -> f.width(220).height(220)),
                                ScaledToFill.with(),
                                Border.with(b -> b.color(Color.BLACK).width(1).radius(8))),
                        Text.with(t -> t.text(computed(() -> MusicPlayerView.at(config.trackIndex.get()).title())))
                                .modifiers(FontSize.with(s -> s.size(20)), FontWeight.BOLD),
                        Text.with(t -> t.text(computed(() -> MusicPlayerView.at(config.trackIndex.get()).artist()
                                + " · " + MusicPlayerView.at(config.trackIndex.get()).album())))
                                .modifiers(ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG))),
                        Divider.modifiers(Padding.with(p -> p.edges(0, 0, 0, 10))),
                        Text.with(t -> t.text("Up Next")).modifiers(FontWeight.SEMIBOLD),
                        upNextRow(1),
                        upNextRow(2));
    }

    /** The track {@code offset} places after the current one. */
    private View upNextRow(int offset) {
        return Text.with(t -> t.text(computed(() -> {
            Track track = MusicPlayerView.at(config.trackIndex.get() + offset);
            return (offset == 1 ? "Up next · " : "Then · ") + track.title() + " — " + track.artist();
        }))).modifiers(FontSize.with(s -> s.size(13)), ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG)));
    }
}

package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.signal.WritableSignal;

import java.util.function.Consumer;

import static com.pathland.view.signal.Signals.computed;

/**
 * A single track row: a cover thumbnail, the title/artist, and the duration.
 * Selecting it starts that track through the app-owned player state, and the
 * current row is highlighted reactively via a computed background/foreground.
 *
 * <p>Configured with {@code TrackRowView.with(r -> r.track(...).index(...)...)} -
 * a private constructor keeps creation on the configurator (spec DSL.md §2).
 */
public final class TrackRowView implements View, Configurable<TrackRowView.Config> {

    /** {@link TrackRowView} values. */
    public static final class Config implements View.Config {

        private Track track;
        private int index;
        private WritableSignal<Integer> trackIndex;
        private WritableSignal<Float> position;
        private WritableSignal<Boolean> playing;
        private WritableSignal<Float> seekRequest;

        /** The track this row represents. */
        public Config track(Track track) {
            this.track = track;
            return this;
        }

        /** The track's index in the library. */
        public Config index(int index) {
            this.index = index;
            return this;
        }

        /** The current track index (drives the highlight). */
        public Config trackIndex(WritableSignal<Integer> trackIndex) {
            this.trackIndex = trackIndex;
            return this;
        }

        /** The play position (seconds), reset on selection. */
        public Config position(WritableSignal<Float> position) {
            this.position = position;
            return this;
        }

        /** Set to true when the row is selected. */
        public Config playing(WritableSignal<Boolean> playing) {
            this.playing = playing;
            return this;
        }

        /** The seek command signal (seconds), reset on selection so the
         *  newly-selected track starts from the beginning. */
        public Config seekRequest(WritableSignal<Float> seekRequest) {
            this.seekRequest = seekRequest;
            return this;
        }
    }

    private final Config config;

    private TrackRowView(Config config) {
        this.config = config;
    }

    /** Configure the track row's values. */
    public static ViewBuilder<TrackRowView, Config> with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new TrackRowView(config));
    }

    /** Apply modifiers to a bare track row. */
    public static ViewBuilder<TrackRowView, Config> modifiers(ViewModifier... modifiers) {
        return new ViewBuilder<>(new TrackRowView(new Config())).modifiers(modifiers);
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public View body() {
        var isCurrent = computed(() -> MusicPlayerView.at(config.trackIndex.get()) == config.track);
        var bg = computed(() -> isCurrent.get() ? MusicPlayerView.ACTIVE_ROW_BG : Color.CLEAR);
        var fg = computed(() -> isCurrent.get() ? MusicPlayerView.ACTIVE_ROW_FG : Color.BLACK);
        return Button
                .modifiers(
                        Background.with(b -> b.color(bg)),
                        ForegroundStyle.with(f -> f.color(fg)),
                        Padding.with(p -> p.uniform(6)),
                        // Full-width row: the layout contract's cross-axis default is hug
                        // (LAYOUT.md), so a row that should span the library column must
                        // explicitly FILL its width.
                        Frame.ofWidth(Commands.Size.FILL))
                .with(b -> b.action(() -> {
                    config.trackIndex.set(config.index);
                    config.position.set(0f);
                    config.seekRequest.set(0f);
                    config.playing.set(true);
                }))
                .children(
                        HStack
                                .with(h -> h.alignment(VerticalAlignment.CENTER).spacing(12f))
                                .children(
                                        Image.with(i -> i.source(config.track.cover())).modifiers(
                                                Frame.with(f -> f.width(44).height(44)),
                                                ScaledToFit.with()),
                                        VStack
                                                .with(v -> v.alignment(HorizontalAlignment.LEADING).spacing(2))
                                                .children(
                                                        Text.with(t -> t.text(config.track.title())).modifiers(FontWeight.SEMIBOLD),
                                                        Text.with(t -> t.text(config.track.artist() + " · " + config.track.album()))
                                                                .modifiers(
                                                                        FontSize.with(s -> s.size(13)),
                                                                        ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG)))),
                                        Spacer.modifiers(),
                                        Text.with(t -> t.text(MusicPlayerView.fmt(config.track.duration())))
                                                .modifiers(
                                                        FontSize.with(s -> s.size(13)),
                                                        ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG)))));
    }
}

package com.pathland.demo.kitchensink;

import com.pathland.view.AccessibilityRole;
import com.pathland.view.ChildrenView;
import com.pathland.view.Commands;
import com.pathland.view.Configurable;
import com.pathland.view.Frame;
import com.pathland.view.Roles;
import com.pathland.view.Text;
import com.pathland.view.View;
import com.pathland.view.ViewBuilder;
import com.pathland.view.ViewModifier;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;

import java.util.List;
import java.util.function.Consumer;
import com.pathland.view.Background;
import com.pathland.view.Border;
import com.pathland.view.CornerRadius;
import com.pathland.view.FontSize;
import com.pathland.view.FontWeight;
import com.pathland.view.ForegroundStyle;
import com.pathland.view.Padding;

/**
 * A reusable kitchen-sink section card: a titled, bordered, rounded container that
 * hosts one section's controls. Demonstrates composition — a custom {@code View}
 * wrapping arbitrary content with style modifiers.
 *
 * <p>Configured with {@code SectionCard.with(s -> s.title(...)).children(content)}
 * — a private constructor keeps creation on the configurator (spec DSL.md §2).
 */
public final class SectionCard implements View, Configurable<SectionCard.Config>, ChildrenView {

    /** {@link SectionCard} values. */
    public static final class Config implements View.Config {

        private Signal<String> title;

        /** Set a static title. */
        public Config title(String title) {
            this.title = Signals.constant(title);
            return this;
        }

        /** Bind the title to a reactive signal. */
        public Config title(Signal<String> title) {
            this.title = title;
            return this;
        }
    }

    private static final Color TITLE_COLOR = Color.rgb(0x55, 0x64, 0x6D);
    private static final Color BORDER = Color.rgb(0xE2, 0xE8, 0xF0);

    private final Config config;
    private List<View> children = List.of();

    private SectionCard(Config config) {
        this.config = config;
    }

    /** Configure the section card's values. */
    public static ViewBuilder<SectionCard, Config> with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new SectionCard(config));
    }

    /** Apply modifiers to a bare section card. */
    public static ViewBuilder<SectionCard, Config> modifiers(ViewModifier... modifiers) {
        return new ViewBuilder<>(new SectionCard(new Config())).modifiers(modifiers);
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public void setChildren(List<View> children) {
        this.children = List.copyOf(children);
    }

    @Override
    public View body() {
        View content = children.isEmpty() ? null : children.get(0);
        return VStack
                .modifiers(
                        Padding.with(p -> p.uniform(16)),
                        Background.with(b -> b.color(Color.WHITE)),
                        Border.with(b -> b.color(BORDER).width(1).radius(10)),
                        CornerRadius.with(c -> c.radius(10)),
                        Frame.ofWidth(Commands.Size.FILL))
                .children(
                        // A section title is a heading → `<h2>`.
                        Text.with(t -> t.text(config.title)).modifiers(
                                FontSize.with(s -> s.size(14)), FontWeight.SEMIBOLD,
                                ForegroundStyle.with(f -> f.color(TITLE_COLOR)),
                                AccessibilityRole.with(a -> a.role(Roles.HEADER))),
                        Divider.modifiers(Padding.with(p -> p.edges(0, 0, 8, 0))),
                        content);
    }
}

