package com.pathland.view;

import java.util.function.Consumer;

/**
 * A bordered, tinted button style: the label padded onto a colored background with a
 * rounded border. The {@link Button} control wires the action on the native button
 * node, so this style only decorates the content.
 *
 * <p>Configured via {@code BorderedButtonStyle.with(b -> b.padding(...).background(...)...)};
 * {@link #INSTANCE} is the default. A private constructor keeps creation on the
 * configurator (spec DSL.md §2).
 */
public final class BorderedButtonStyle implements ButtonStyle {

    public static final BorderedButtonStyle INSTANCE = new BorderedButtonStyle(new Config());

    /** {@link BorderedButtonStyle} values. */
    public static final class Config implements View.Config {

        private float padding = 10f;
        private Color background = Color.rgb(33, 150, 243);
        private Color borderColor = Color.rgb(25, 118, 210);
        private float radius = 6f;

        /** The label padding. */
        public Config padding(float padding) {
            this.padding = padding;
            return this;
        }

        /** The background color. */
        public Config background(Color background) {
            this.background = background;
            return this;
        }

        /** The border color. */
        public Config borderColor(Color borderColor) {
            this.borderColor = borderColor;
            return this;
        }

        /** The corner radius. */
        public Config radius(float radius) {
            this.radius = radius;
            return this;
        }
    }

    private final Config config;

    private BorderedButtonStyle(Config config) {
        this.config = config;
    }

    /** Configure a bordered style ({@code BorderedButtonStyle.with(b -> …)}). */
    public static BorderedButtonStyle with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new BorderedButtonStyle(config);
    }

    @Override
    public View makeBody(Configuration config) {
        return config.label().with(
                        ForegroundStyle.with(f -> f.color(Color.WHITE)),
                        Padding.with(p -> p.uniform(this.config.padding)),
                        Background.with(b -> b.color(this.config.background)),
                        Border.with(b -> b.color(this.config.borderColor).width(1f).radius(this.config.radius)));
    }
}

package com.pathland.processor;

import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.ExecutableElement;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.lang.model.type.TypeMirror;
import javax.lang.model.util.Elements;
import javax.lang.model.util.Types;
import javax.tools.Diagnostic;
import java.util.List;
import java.util.Set;

/**
 * Enforces the **configurator convention** (spec DSL.md §2) for the two
 * authoring surfaces that take a value config:
 *
 * <ul>
 *   <li>a custom {@code com.pathland.view.View}, and</li>
 *   <li>a custom style ({@code com.pathland.view.Style} — {@code ButtonStyle},
 *       {@code LabelStyle}, {@code AudioStyle}, {@code VideoStyle} implementations).</li>
 * </ul>
 *
 * <p>Both are configured through a static {@code with(Consumer<Config>)} factory,
 * never a parameterized constructor. Any non-abstract class assignable to
 * {@code View} or {@code Style} that exposes a {@code public}/{@code protected}
 * constructor **with ≥ 1 parameter** is a compile error — creation must go
 * through the configurator that a {@code Config} + private constructor exist for
 * (a no-arg constructor is legal: config-less roots like {@code new MyView()}
 * may still be mounted directly).
 *
 * <p>Types are detected by assignability (no annotation), only for classes part
 * of this compilation round (application views/styles), never library/jar types.
 * Abstract classes are exempt (they cannot be instantiated), and enums/records/
 * interfaces are skipped (they cannot expose a parameterized public constructor
 * in the flagged form).
 *
 * <p>Opt-in per module: add this jar (pathland-view-processor) to the module's
 * {@code annotationProcessorPaths} (the same wiring that activates
 * {@link PersistedProcessor} for {@code State} binders).
 */
@SupportedAnnotationTypes("*")
public final class ViewAuthoringProcessor extends AbstractProcessor {

    @Override
    public SourceVersion getSupportedSourceVersion() {
        return SourceVersion.latestSupported();
    }

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        if (roundEnv.processingOver()) {
            return false;
        }
        Elements elements = processingEnv.getElementUtils();
        Types types = processingEnv.getTypeUtils();
        TypeElement viewType = elements.getTypeElement("com.pathland.view.View");
        if (viewType == null) {
            return false; // pathland-view not on the processing classpath
        }
        TypeMirror caught = types.erasure(viewType.asType());
        TypeElement styleType = elements.getTypeElement("com.pathland.view.Style");
        TypeMirror styleErasure = styleType == null ? null : types.erasure(styleType.asType());

        for (Element root : roundEnv.getRootElements()) {
            if (!(root instanceof TypeElement type) || type.getKind() != ElementKind.CLASS) {
                continue;
            }
            TypeMirror erasure = types.erasure(type.asType());
            boolean isView = types.isAssignable(erasure, caught);
            boolean isStyle = styleErasure != null && types.isAssignable(erasure, styleErasure);
            if (!isView && !isStyle) {
                continue;
            }
            if (type.getModifiers().contains(Modifier.ABSTRACT)) {
                continue; // abstract types can't be instantiated — configurator may not apply
            }
            String surface = isStyle ? "Style" : "View";
            for (ExecutableElement constructor : constructorsOf(type)) {
                if (isAccessible(constructor) && !constructor.getParameters().isEmpty()) {
                    processingEnv.getMessager().printMessage(
                            Diagnostic.Kind.ERROR,
                            type.getSimpleName() + " exposes a " + accessibilityOf(constructor)
                                    + " constructor with parameters: " + constructor
                                    + " — a custom " + surface + " must be configured via its static "
                                    + type.getSimpleName() + ".with(Consumer<Config>) factory (spec DSL.md §2);"
                                    + " keep the constructor private and expose the values on the nested Config.",
                            constructor);
                }
            }
        }
        return false;
    }

    private static List<ExecutableElement> constructorsOf(TypeElement type) {
        return type.getEnclosedElements().stream()
                .filter(e -> e.getKind() == ElementKind.CONSTRUCTOR)
                .map(e -> (ExecutableElement) e)
                .toList();
    }

    private static boolean isAccessible(ExecutableElement constructor) {
        return constructor.getModifiers().contains(Modifier.PUBLIC)
                || constructor.getModifiers().contains(Modifier.PROTECTED);
    }

    private static String accessibilityOf(ExecutableElement constructor) {
        return constructor.getModifiers().contains(Modifier.PUBLIC) ? "public" : "protected";
    }
}

package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.signal.WritableSignal;

import java.util.function.Consumer;

import static com.pathland.view.signal.Signals.computed;

/**
 * The music player's custom {@link AudioStyle}: the full bottom-bar surface —
 * a centered row of {@code [rewind] [play-pause] [forward] | [cover art]
 * [track title] | [volume]} over a slim, draggable seek bar that reports
 * <b>progress as a percent</b> (mapped in the UI model via {@link PercentSeek};
 * the wire keeps seconds). Everything binds to the media configuration's
 * signals, so this becomes the {@code AUDIO} node's children and the renderer
 * emits a hidden media element alongside these app-defined controls (real
 * playback, app-driven).
 *
 * <p>Configured via {@code PlayerControlsStyle.with(s -> s.trackIndex(...)…)} —
 * a private constructor keeps creation on the configurator (spec DSL.md §2).
 */
public final class PlayerControlsStyle implements AudioStyle {

    /** {@link PlayerControlsStyle} values: the DISPLAY signals (fed by the media
     *  reports) and the SEEK/VOLUME command signals (written on user drags). */
    public static final class Config implements View.Config {

        private WritableSignal<Integer> trackIndex;
        private WritableSignal<Float> position;
        private WritableSignal<Float> seekRequest;
        private WritableSignal<Float> volume;
        private WritableSignal<Float> volumeRequest;

        /** The current track index. */
        public Config trackIndex(WritableSignal<Integer> trackIndex) {
            this.trackIndex = trackIndex;
            return this;
        }

        /** The play-position DISPLAY signal (fed by the media reports). */
        public Config position(WritableSignal<Float> position) {
            this.position = position;
            return this;
        }

        /** The SEEK command signal (written on user drags). */
        public Config seekRequest(WritableSignal<Float> seekRequest) {
            this.seekRequest = seekRequest;
            return this;
        }

        /** The volume DISPLAY signal (fed by the media reports). */
        public Config volume(WritableSignal<Float> volume) {
            this.volume = volume;
            return this;
        }

        /** The VOLUME command signal (written on user drags). */
        public Config volumeRequest(WritableSignal<Float> volumeRequest) {
            this.volumeRequest = volumeRequest;
            return this;
        }
    }

    private final Config config;

    private PlayerControlsStyle(Config config) {
        this.config = config;
    }

    /** Configure the player-controls style's signals. */
    public static PlayerControlsStyle with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new PlayerControlsStyle(config);
    }

    @Override
    public View makeBody(Configuration configuration) {
        var current = computed(() -> MusicPlayerView.at(config.trackIndex.get()));
        var transportIcon = computed(() -> configuration.playing().get() ? IconName.PAUSE.wire() : IconName.PLAY.wire());
        var seek = new SeekControl(config.position, config.seekRequest);
        var volumeControl = new VolumeControl(config.volume, config.volumeRequest);

        var playControl = HStack
                .with(h -> h.alignment(VerticalAlignment.CENTER).spacing(18f))
                .children(
                        Button
                                .modifiers(FontSize.with(s -> s.size(20)))
                                .with(b -> b.action(() -> { prev(); restartSeek(); }))
                                .children(Icon.with(i -> i.name(IconName.SKIP_BACK))),
                        Button
                                .modifiers(FontSize.with(s -> s.size(28)))
                                .with(b -> b.action(() -> configuration.playing().update(v -> !v)))
                                .children(Icon.with(i -> i.name(transportIcon))),
                        Button
                                .modifiers(FontSize.with(s -> s.size(20)))
                                .with(b -> b.action(() -> { next(); restartSeek(); }))
                                .children(Icon.with(i -> i.name(IconName.SKIP_FORWARD))));
        var trackInfo = HStack
                .with(h -> h.alignment(VerticalAlignment.CENTER).spacing(18f))
                .children(
                        Image.with(i -> i.source(computed(() -> current.get().cover()))).modifiers(
                                Frame.with(f -> f.width(36).height(36)),
                                ScaledToFit.with()),
                        VStack
                                .modifiers(Frame.with(f -> f.width(160f)))
                                .with(v -> v.alignment(HorizontalAlignment.LEADING).spacing(2))
                                .children(
                                        Text.with(t -> t.text(computed(() -> current.get().title())))
                                                .modifiers(FontWeight.SEMIBOLD, LineLimit.with(l -> l.value(1))),
                                        Text.with(t -> t.text(computed(() -> current.get().artist())))
                                                .modifiers(
                                                        FontSize.with(s -> s.size(13)),
                                                        ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG)),
                                                        LineLimit.with(l -> l.value(1)))));

        var volumeView = HStack
                .with(h -> h.alignment(VerticalAlignment.CENTER).spacing(18f))
                .children(
                        Icon.with(i -> i.name(IconName.VOLUME)).modifiers(FontSize.with(s -> s.size(16))),
                        Slider.with(s -> s.value(volumeControl).in(0f, 1f)));

        var compactControls = HStack
                .with(h -> h.alignment(VerticalAlignment.CENTER).spacing(18f))
                .children(
                        playControl,
                        Text.with(t -> t.text("|")).modifiers(FontSize.with(s -> s.size(18)), ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG))),
                        trackInfo);

        var controls = HStack
                .with(h -> h.alignment(VerticalAlignment.CENTER).spacing(18f))
                .children(
                        playControl,
                        Text.with(t -> t.text("|")).modifiers(FontSize.with(s -> s.size(18)), ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG))),
                        trackInfo,
                        Text.with(t -> t.text("|")).modifiers(FontSize.with(s -> s.size(18)), ForegroundStyle.with(f -> f.color(MusicPlayerView.SECONDARY_FG))),
                        volumeView);

        var groups = SizeThatFits.with(
                Fit.of(controls, 600),
                Fit.of(compactControls)
        );

        return VStack
                .with(v -> v.alignment(HorizontalAlignment.CENTER).spacing(0))
                .children(
                        // Centered groups over a full-width seek bar (the slider's FILL
                        // width spans the bar via fill propagation; the groups stay
                        // centered above it).
                        groups,
                        Slider.with(s -> s.value(new PercentSeek(seek,
                                        () -> MusicPlayerView.at(config.trackIndex.get()).duration()))
                                .in(0f, 100f).onEditingChanged(seek::onEditingChanged))
                                .modifiers(
                                        Frame.with(f -> f.width(Float.POSITIVE_INFINITY)),
                                        Padding.with(p -> p.edges(0, 16, 0, 16))));
    }

    /** Previous track (wraps around); the seek restarts via the command binding. */
    private void prev() {
        config.trackIndex.update(i -> (i - 1 + MusicPlayerView.TRACKS.size()) % MusicPlayerView.TRACKS.size());
    }

    /** Next track (wraps around); the seek restarts via the command binding. */
    private void next() {
        config.trackIndex.update(i -> (i + 1) % MusicPlayerView.TRACKS.size());
    }

    /** A prev/next restart seeks to the top: reset both the display and the command. */
    private void restartSeek() {
        config.position.set(0f);
        config.seekRequest.set(0f);
    }
}

