fn fit_band_styles(nodes: &BTreeMap<u32, Node>) -> String {
    let mut rules = String::new();
    for (id, node) in nodes {
        if node.component != component_type::SIZE_THAT_FITS || node.children.len() < 2 {
            continue;
        }
        // One `@container` rule per distinct threshold band, mirroring the fit rule
        // (`max{ i : T_i <= width }`, equal thresholds pick the lower index): at
        // `width >= T_i` candidate i becomes visible and candidate i-1 (the previous
        // band's fallback) hides; later duplicates of the same threshold stay hidden.
        let thresholds = &node.fit_thresholds;
        let mut prev: Option<f32> = None;
        for (i, &t) in thresholds.iter().enumerate() {
            if i == 0 {
                prev = Some(t);
                continue; // candidate 0 is the default-visible fallback
            }
            // Equal thresholds → the lower index wins; skip later duplicates.
            if prev.map_or(false, |p| (p - t).abs() < f32::EPSILON) {
                continue;
            }
            let prev_idx = i - 1;
            rules.push_str(&format!(
                "@container pf-{id} (min-width: {t}px) {{ \
                   [data-pathland-id=\"{prev_idx}\"][data-pathland-cand=\"{prev_idx}\"] {{ display: none; }} \
                   [data-pathland-id=\"{id}\"][data-pathland-fit-cand=\"{prev_idx}\"] {{ }} \
                 }} \n",
            ));
            rules.push_str(&format!(
                "@container pf-{id} (min-width: {t}px) {{ \
                   [data-pathland-cand=\"{prev_idx}\"] {{ display: none; }} \
                 }} \n",
            ));
            // Candidate i shows from its own threshold onward; it stays hidden below
            // it (default `display:none` on wrappers i ≥ 1).
            rules.push_str(&format!(
                "@container pf-{id} (min-width: {t}px) {{ [data-pathland-cand=\"{i}\"] {{ display: contents; }} }} \n",
            ));
            // Hide anything below the band (candidate i-1 was shown by default / by
            // its own rule), so exactly one candidate is visible at a time.
            rules.push_str(&format!(
                "@container pf-{id} (min-width: {t}px) {{ \
                   [data-pathland-cand], [data-pathland-id=\"{id}\"] > [data-pathland-cand] {{ display: none; }} \
                   [data-pathland-cand=\"{i}\"] {{ display: contents; }} \
                 }} \n",
            ));
            prev = Some(t);
        }
    }
    rules
}

