/**
 * Remove a slot's `@container pf-<id>` band rules from the managed
 * `style[data-pathland-fit]` element (created by the SSR head or the client's
 * rule manager). Called when a snapshot slot collapses to the live single-child
 * form — the leftover rules would otherwise keep gating nothing (harmless), but
 * the element must not grow stale rules across resyncs.
 */
function dropFitBandRules(slotId: number): void {
  const style = document.querySelector<HTMLStyleElement>("style[data-pathland-fit]");
  if (!style) return;
  const marker = `pf-${slotId}`;
  const sheet = style.sheet;
  if (sheet && Array.from(sheet.cssRules).length > 0) {
    try {
      const keep = Array.from(sheet.cssRules)
        .map((rule) => rule.cssText)
        .filter((text) => !text.includes(marker));
      sheet.replaceSync?.(keep.join("\n"));
      return;
    } catch {
      // fall through to the text filter
    }
  }
  // happy-dom / older engines: filter the source text directly. A `@container
  // pf-<id> (...)` rule ends at its matching `}`; strip the block conservatively
  // by removing each `@container pf-<id>` … `}` segment.
  const blocks = style.textContent?.split(/\n/) ?? [];
  const kept: string[] = [];
  let skip = false;
  for (const line of blocks) {
    if (!skip && line.includes(`@container pf-${slotId}`)) {
      skip = true;
    }
    if (skip) {
      if (line.includes("}")) {
        skip = false;
      }
      continue;
    }
    kept.push(line);
  }
  style.textContent = kept.join("\n");
}

