/// The `@container` band rules for every multi-candidate fit slot, rendered into
/// a `<style data-pathland-fit>` element in the document head (issue #141). For
/// each distinct threshold `T_i` (ascending): at `width >= T_i` show candidate
/// `i` and hide every other candidate of THIS slot (candidate wrappers carry
/// `data-pathland-fit-cand`; selectors are scoped to the slot's
/// `data-pathland-id`), so exactly one candidate is visible at any container
/// width — mirroring `pathland_core::fit::fit_index` (equal thresholds pick the
/// lower index, so later duplicates never get a rule).
fn fit_band_styles(nodes: &BTreeMap<u32, Node>) -> String {
    let mut rules = String::new();
    for (id, node) in nodes {
        if node.component != component_type::SIZE_THAT_FITS || node.children.len() < 2 {
            continue;
        }
        let mut seen = f32::NEG_INFINITY;
        for (i, &t) in node.fit_thresholds.iter().enumerate() {
            if i == 0 {
                seen = t;
                continue; // candidate 0 is the default-visible fallback
            }
            if t <= seen {
                continue; // equal threshold → lower index already owns the band
            }
            seen = t;
            rules.push_str(&format!(
                "@container pf-{id} (min-width: {t}px) {{ \
                   [data-pathland-id=\"{id}\"] > [data-pathland-fit-cand] {{ display: none !important; }} \
                   [data-pathland-id=\"{id}\"] > [data-pathland-fit-cand=\"{i}\"] {{ display: contents !important; }} \
                 }} \n",
            ));
        }
    }
    rules
}

