import com.pathland.view.Color;
import com.pathland.view.Components;
import com.pathland.view.Environment;

public void renderFull() {
    if (!mounted) {
        throw new IllegalStateException("Emitter not mounted");
    }
    // A resync is a full frame delivered as OPCODES — the web renderer's
    // snapshot gating (candidate wrappers + `@container` band rules) is
    // HTML-only and cannot ride the opcode stream. So a fit slot that has not
    // yet received its first FIT_CHANGED is collapsed to its selected single
    // child here, rather than resyncing an ungated multi-candidate slot
    // (issue #141, spec/PRIMITIVES.md §SizeThatFits hydration contract).
    collapseUnreportedSnapshotSlots(tree);
    sink.beginFrame();
    emitTheme();
    // The retained tree already carries every fit candidate when the session
    // mounted in snapshot mode; re-emit it as-is (a resync re-establishes the
    // container-query first paint for a reconnecting client).
    emitNode(tree);
    sink.endFrame();
}

/**
 * Collapse any not-yet-reported full-snapshot fit slot to its selected single
 * child, in place, so a resync emits the live single-child form. Drops the
 * unselected candidates' bindings + inputs (they leave the tree).
 */
private void collapseUnreportedSnapshotSlots(PathlandNode node) {
    if (node.component == Components.SIZE_THAT_FITS
            && node.children.size() > 1 && !node.fitReported) {
        int index = Math.min(Math.max(node.fitSelection, 0), node.children.size() - 1);
        PathlandNode keep = node.children.get(index);
        List<PathlandNode> dropped = new ArrayList<>(node.children);
        dropped.remove(index);
        destroySubtreeBindings(dropped);
        forgetInputs(dropped);
        node.children.clear();
        node.children.add(keep);
        node.fitReported = true;
    }
    for (PathlandNode child : new ArrayList<>(node.children)) {
        collapseUnreportedSnapshotSlots(child);
    }
}

