import { readFileSync } from "node:fs";
import { expect, it } from "vitest";
import { applyBatch, type DomRenderer } from "../src/apply";
import { parseBatch } from "../src/plpl";
import { buildBatch } from "./plpl.test";
import { CAT_TREE, CMD_CREATE_NODE, CMD_DELETE_NODE, CMD_INSERT_CHILD, CMD_REMOVE_CHILD } from "../src/constants";

const REAL = "/var/folders/5p/0d4szgs13t5b74h2c379j3gc0000gn/T/opencode/ssr.html";

function hydrate(): { r: DomRenderer; slot: HTMLElement } {
  const html = readFileSync(REAL, "utf8");
  const body = html.slice(html.indexOf("<body>") + 6, html.indexOf("</body>"));
  document.body.innerHTML = body;
  const r: DomRenderer = { byId: new Map() };
  for (const el of document.querySelectorAll("[data-pathland-id]")) {
    r.byId.set(Number(el.getAttribute("data-pathland-id")), el);
  }
  return { r, slot: r.byId.get(1) as HTMLElement };
}

it("real SSR: a resync replay leaves the gate intact (both candidates wrapped)", () => {
  const { r, slot } = hydrate();
  expect(slot.hasAttribute("data-pathland-fit-cands")).toBe(true);

  // Resync-shaped replay: CREATE the existing slot + insert the existing candidates.
  applyBatch(
    parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, 0x17],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2, 0],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 115, 1],
      ]),
    ),
    r,
  );

  const wrappers = Array.from(slot.children).filter((c) => c.hasAttribute("data-pathland-fit-cand"));
  expect(wrappers.length).toBe(2);
  expect(slot.style.containerName).toBe("pf-1");
});

it("real SSR: the downgrade removal tears the gate down + keeps the wide candidate", () => {
  const { r, slot } = hydrate();

  applyBatch(
    parseBatch(
      buildBatch([
        [CAT_TREE, CMD_REMOVE_CHILD, 0, 1, 2],
        [CAT_TREE, CMD_DELETE_NODE, 0, 2],
      ]),
    ),
    r,
  );

  const directWrappers = Array.from(slot.children).filter((c) => c.hasAttribute("data-pathland-fit-cand"));
  expect(directWrappers.length).toBe(0);
  expect(slot.hasAttribute("data-pathland-fit-cands")).toBe(false);
  expect(slot.children.length).toBe(1);
  expect(slot.firstElementChild?.getAttribute("data-pathland-id")).toBe("115");
  expect(slot.textContent ?? "").toContain("Now Playing");
});

